//! Shared test vectors, generated by the independent Python reference
//! implementation (scripts/make_vectors.py). Every language implementation
//! must reproduce them exactly.

use gnomon_core::json::{self, canonical};
use gnomon_core::sha256::hex_digest;

#[test]
fn shared_canonical_vectors() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/vectors/canonical.json"
    );
    let text = std::fs::read_to_string(path).expect("vectors file");
    let vectors = json::parse(&text).expect("vectors parse");
    let items = vectors.as_array().expect("array");
    assert!(items.len() > 10);
    for v in items {
        let input = v.get("input").unwrap().as_str().unwrap();
        let expected = v.get("canonical").unwrap().as_str().unwrap();
        let sha = v.get("sha256").unwrap().as_str().unwrap();
        let got = canonical(&json::parse(input).unwrap());
        assert_eq!(got, expected, "input {input}");
        assert_eq!(hex_digest(got.as_bytes()), sha, "input {input}");
    }
}
